function course1(){return `<main id="main">${intro('COURSE 1.0 / AI 启蒙与应用','AI启蒙与应用1.0<br>课程内容研发与更新','面向6-12岁儿童的AI启蒙与应用课程。本人参与全部课程内容的撰写与审校，并根据工具功能变化、用户反馈和教学需要，持续更新课程脚本。','PROJECT / 1.0')}<div class="wrap"><section class="featured"><div class="featured-copy"><div class="eyebrow">01 / 项目介绍</div><h2>认识AI，<br>也学会使用AI。</h2><p>项目整体包含53节课程，将AI认知、基础操作、学习辅助与创意表达相结合，通过故事、动画和实际操作组织学习。</p><p class="micro">AI启蒙与应用｜课程预告片</p></div>${promoVisual()}</section><section class="text-section">${sectionTitle('COURSE OVERVIEW','课程如何组织？')}<div class="outline-list">${courseThemes.map(([a,b],i)=>`<details ${i===0?'open':''}><summary>${String(i+1).padStart(2,'0')} &nbsp;${a}</summary><p>${b}</p></details>`).join('')}</div></section><section class="text-section">${sectionTitle('02 / 本人工作','从内容撰写，<br>到审校与更新。')}<div class="rich"><article class="delivery-case"><h3>全课程内容撰写与审校</h3><p>参与全部内容的撰写与审校，包括课程内容、制作脚本与物料文案，结合动画、图书和实际操作检查教学表达，并与制作团队衔接。</p></article><article class="delivery-case"><h3>课程内容持续迭代</h3><p>根据AI工具更新变化、用户反馈与审校意见，持续更新并修改、补充课程内容。</p></article><article class="delivery-case"><h3>细化制作脚本</h3><p>将课程内容细化为角色台词、画面、动作及录屏节点，衔接动画与录屏制作，并交付给制作团队。</p></article></div></section><section class="case-study" id="case-method"><div class="eyebrow">LEARNING DESIGN / 设计方法</div><h2>从内容，到可以制作的镜头。</h2><p class="case-lead">将课程内容转化为可执行的制作脚本，明确教学表达、视觉画面与操作演示之间的对应关系。</p><div class="case-steps"><article><span>01</span><h3>教学表达</h3><p>将知识和操作融入角色台词，使故事情节与学习任务相连。</p></article><article><span>02</span><h3>制作衔接</h3><p>补充画面、动作和录屏节点，让脚本能够与动画及录屏制作对接。</p></article><article><span>03</span><h3>内容迭代</h3><p>结合工具变化、反馈和审校意见更新课程；参与内容研发与制作团队协作。</p></article></div></section><section class="text-section" id="deliverables">${sectionTitle('03 / 本人产出','课程内容<br>与配套成果','覆盖课程的内容研发、制作衔接、配套物料和内容审校。')}<div><div class="course-deliverables"><article><span>01 / CONTENT</span><h3>课程内容与教研材料</h3><p>参与形成课程框架与教研材料，并参与全课程内容的撰写与审校，覆盖AI认知、操作、应用及安全与伦理。</p></article><article><span>02 / PRODUCTION</span><h3>动画与录屏制作脚本</h3><p>将课程内容细化为角色台词、画面、动作与录屏节点，形成供动画及录屏制作衔接的脚本。</p></article><article><span>03 / MATERIALS</span><h3>课程配套物料文案</h3><p>撰写实体物料等配套内容文案，使课程中的讲解、任务与练习形成连贯的学习体验。</p></article><article><span>04 / REVIEW</span><h3>内容审校与修订稿</h3><p>参与图书与动画内容审校，整理并落实修改意见，形成相应的内容修订稿。</p></article></div><article class="delivery-case" id="course-updates" style="margin-top:32px;border-top:1px solid #d5d7cb;padding-top:26px"><h3>课程更新与新增</h3><p>完成7节课程脚本的更新与新增，相关脚本已完成并进入制作阶段。</p></article></div></section><section class="text-section" id="course-materials">${sectionTitle('SELECTED MATERIALS','课程内容与配套物料','通过课程画面、内容大纲、配套图书与实体学习物料，呈现课程从线上内容到线下练习的完整学习体验。动画与视觉由项目团队协作完成。')}<div><h3>课程画面</h3><div class="course-stills">${D.courseStills.map(x=>`<figure>${im(x.src,x.title)}<figcaption>${esc(x.title)}</figcaption></figure>`).join('')}</div><div class="material-grid">${[['10','课程内容大纲 · 上'],['11','课程内容大纲 · 下'],['07','配套AI启蒙图书'],['09','AI启蒙主题礼盒与学习物料']].map(([n,title])=>`<figure><button data-asset="assets/course-material-${n}.jpg" data-title="${title}" aria-label="查看${title}">${im('assets/course-material-'+n+'.jpg',title)}</button><figcaption>${title}</figcaption></figure>`).join('')}</div></div></section></div></main>`}
function course2(){return `<main id="main">${intro('COURSE 2.0 / 21 天玩转豆包','21天玩转豆包2.0<br>课程方案与Demo设计','围绕儿童学习、生活与创作任务，设计AI应用课程。本人参与项目方案与内容规划，编排课程大纲，并撰写第一课Demo脚本。','PROJECT / 2.0')}<div class="wrap"><section class="course2-poster"><h2 class="sr-only">项目介绍</h2><div class="eyebrow">01 / 项目介绍</div>${im('assets/course2-overview.png','21天玩转豆包课程介绍海报','',true)}</section><section class="text-section">${sectionTitle('02 / 本人工作','将AI功能，<br>转化为教学任务。')}<div class="rich"><article class="delivery-case"><h3>参与项目方案与课程规划</h3><p>梳理目标、内容方向与学习路径，将工具能力连接到儿童的实际学习和生活场景。</p></article><article class="delivery-case"><h3>编排课程内容大纲</h3><p>整理对话、图像理解、学习辅助和多模态创作功能，形成课程主题与任务安排。</p></article><article class="delivery-case"><h3>撰写第一课Demo</h3><p>围绕植物观察与学习任务设计情境、角色台词、操作演示、检查方法和课后任务。</p></article></div></section><section class="section course2-outputs" id="course2-deliverables"><div class="eyebrow">03 / 本人产出</div><h2>课程方案、大纲与第一课Demo</h2><div class="output-group"><h3>产出一｜课程方案与内容大纲</h3><p>交付项目方案与21天课程内容大纲，梳理课程目标、学习路径、主题与任务安排。</p><div class="phase-grid clear-phases">${days.map(([n,t,d,list],i)=>`<article class="phase-card clear-phase"><div class="phase-heading"><span>阶段${['一','二','三'][i]}</span><strong>第${n.split('—').map(Number).join('—')}天</strong></div><h3>${t}</h3><p>${d}</p><ul>${list.map(y=>`<li>${y}</li>`).join('')}</ul></article>`).join('')}</div></div><div class="output-group" id="demo-script"><h3>产出二｜第一课Demo</h3><h4>豆包，快看看这是什么！</h4><p>交付第一课Demo脚本，包含教学情境、角色台词、操作演示、核对方法与课后任务。以植物园里的含羞草为情境，将观察、提问、核对与迁移串联成学习任务。</p><div class="lesson-journey"><figure class="task-output"><span>学习任务 · 观察记录示意</span><div class="plant-mark" aria-hidden="true">✳</div><h3>今日发现：叶子会合起来</h3><p>看到的现象 → 想问的问题 → 核对的信息</p><figcaption>先观察，再提问，最后检查答案。</figcaption></figure>${[['01','发现问题','轻碰叶子后，它为什么合起来了？','从孩子能够观察到的现象开始。'],['02','表达与追问','这是什么植物？为什么会这样？','引导孩子对准观察对象，说清自己的问题。'],['03','检查答案','对照植物园的介绍牌。','把AI回答和现场信息相互核对。'],['04','迁移练习','将“说清要求—尝试—检查”用到学习任务。','延伸到听写与结果检查，形成可复用的方法。']].map(([n,t,q,d])=>`<details class="journey-step" ${n==='01'?'open':''}><summary><span>${n}</span><h3>${t}</h3><i>＋</i></summary><div><p class="journey-question">${q}</p><p>${d}</p></div></details>`).join('')}</div></div></section></div></main>`}
function notes(){return `<main id="main">${intro('NOTES / 关于本站','作品与实践','AI内容创作、生产流程设计与儿童AI课程研发。','NOTES')}<div class="wrap credits"><h2>工作方向</h2><p>以内容表达连接品牌传播，以SOP和Skill支持持续生产，以学习任务组织儿童AI课程。</p><h2>实践领域</h2><p>AI新媒体视频、信息流广告素材、品牌GEO内容与儿童AI课程研发。</p></div></main>`}

